func demoContactAvatarB64(contactID string) string {
	if b64, ok := demoContactAvatars[contactID]; ok {
		return b64
	}
	// Cycle the six bundled portraits for extra demo contacts (c07+) so new
	// rows still show varied avatars without shipping new binary assets.
	keys := []string{"c01", "c02", "c03", "c04", "c05", "c06"}
	h := 0
	for i := 0; i < len(contactID); i++ {
		h = h*31 + int(contactID[i])
	}
	if h < 0 {
		h = -h
	}
	return demoContactAvatars[keys[h%len(keys)]]
}

func demoAppIconPNG(app string) string {
	if b64, ok := demoAppIcons[app]; ok {
		return b64
	}
	return demoAppIcons["Messages"]
}

func demoSongCoverArtB64() string {
	return demoSongCoverB64
}

func demoPhotoThumbB64(photoID string) string {
	if b64, ok := demoPhotoThumbs[photoID]; ok {
		return b64
	}
	if alias, ok := demoPhotoAliases[photoID]; ok {
		if b64, ok := demoPhotoThumbs[alias]; ok {
			return b64
		}
	}
	return demoPhotoThumbs["p01"]
}

func demoPhotoHiResB64(photoID string) string {
	if b64, ok := demoPhotoHiRes[photoID]; ok {
		return b64
	}
	// No dedicated high-res asset: the correct image at thumb
	// resolution beats a sharp wrong one.
	return demoPhotoThumbB64(photoID)
}

// demoPhotoAliases stretches the demo library with more pictures without
// embedding more megabytes of JPEG: extra IDs reuse earlier thumbnails
// under older timestamps, so the grid reads like months of camera roll.
var demoPhotoAliases = map[string]string{
	"p22": "p08", "p23": "p03", "p24": "p11", "p25": "p06",
	"p26": "p14", "p27": "p01", "p28": "p17", "p29": "p05",
	"p30": "p19", "p31": "p09", "p32": "p13", "p33": "p20",
	"p34": "p04", "p35": "p16", "v06": "v03", "v07": "v05",
}

func demoSampleMP4() []byte {
	demoVideoOnce.Do(func() {
		b, err := base64.StdEncoding.DecodeString(demoVideoB64)
		if err == nil {
			demoVideoData = b
		}
	})
	return demoVideoData
}
